function applyWeather(value,wet=0){const night=value==='night',sunset=value==='sunset',rain=value==='storm'||value==='light'||wet>.2;const top=night?'#09131e':rain?'#667984':sunset?'#627e91':'#69a4c1',bottom=night?'#293b4a':rain?'#a3afb0':sunset?'#edd0a6':'#d3e3d7';skyMat.uniforms.top.value.set(top);skyMat.uniforms.bottom.value.set(bottom);scene.fog.color.set(bottom);scene.fog.near=rain?120:250;scene.fog.far=rain?850:1900;hemi.intensity=night?.8:rain?1.5:2.1;hemi.color.set(night?0x8cabd5:0xe5eef9);sun.intensity=night?.6:rain?.75:sunset?3.1:3.5;sun.color.set(sunset?0xffbd7c:night?0xa8c5ed:0xfff4d8);renderer.toneMappingExposure=night?.95:1.08;if(roadMaterial){roadMaterial.roughness=lerp(.94,.16,wet);roadMaterial.metalness=lerp(.02,.45,wet);roadMaterial.color.set(wet>.3?0x8d9eaa:0xffffff);}}
