function updateTrackCard(){$('trackName').textContent=track.name;$('trackCountry').textContent=track.country;$('trackIndex').textContent=String(trackIndex+1).padStart(2,'0')+' / 06';$('trackLength').textContent=(track.length/1000).toFixed(2).replace('.',',');$('trackTurns').textContent=track.turns;drawMap($('trackPreview'));}
