function updateDash(){const p=race?.player||{gear:0,speed:0,fuel:strategy.fuel,battery:100,temp:78,condition:1},d=playerMesh.userData.dash,ctx=d.ctx;ctx.fillStyle='#061016';ctx.fillRect(0,0,512,256);ctx.fillStyle='#a2e247';ctx.fillRect(0,0,512,4);ctx.font='bold 16px monospace';ctx.fillStyle='#c0d2cf';ctx.textAlign='left';ctx.fillText('APEX / TELEMETRY',16,27);ctx.textAlign='right';ctx.fillStyle=race?.drs?'#d8ff3e':'#42616c';ctx.fillText(race?.drs?'DRS ACTIVE':'DRS',494,27);ctx.textAlign='left';ctx.fillStyle='#fff';ctx.font='bold 115px monospace';ctx.fillText(p.speed>1?p.gear:'N',25,145);ctx.font='bold 79px monospace';ctx.textAlign='right';ctx.fillText(Math.round(p.speed*3.6),483,127);ctx.font='16px monospace';ctx.fillStyle='#86a4aa';ctx.fillText('KM/H',480,154);ctx.textAlign='left';ctx.fillStyle='#344b56';ctx.fillRect(18,173,475,8);ctx.fillStyle='#d8ff3e';ctx.fillRect(18,173,475*p.battery/100,8);ctx.font='19px monospace';ctx.fillStyle='#e1ecdd';ctx.fillText('ERS '+Math.round(p.battery)+'%',18,212);ctx.fillText('F '+p.fuel.toFixed(1),190,212);ctx.fillText(Math.round(p.temp)+'°C',365,212);ctx.font='15px monospace';ctx.fillStyle='#8da9b1';ctx.fillText('P'+(race?.position||10)+'  L'+(race?.lap()||1)+'   TYRE '+Math.round(p.condition*100)+'%',18,242);d.texture.needsUpdate=true;playerMesh.userData.leds.forEach((l,i)=>l.material.color.set((race?.rpm||4000)>5500+i*600?(i<4?0x76e067:i<8?0xfede44:0xfa3452):0x243137));}
