function initAudio(){if(audioState.ctx)return;try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),master=ctx.createGain();master.gain.value=0;master.connect(ctx.destination);audioState.ctx=ctx;audioState.gain=master;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1800;filter.connect(master);audioState.filter=filter;for(const [type,detune]of [['sawtooth',0],['triangle',8],['sawtooth',-1200]]){const o=ctx.createOscillator();o.type=type;o.detune.value=detune;o.frequency.value=80;const gain=ctx.createGain();gain.gain.value=.12;o.connect(gain);gain.connect(filter);o.start();audioState.voices.push(o);}const buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const noise=ctx.createBufferSource();noise.buffer=buffer;noise.loop=true;const nf=ctx.createBiquadFilter();nf.type='lowpass';nf.frequency.value=700;const ng=ctx.createGain();ng.gain.value=0;noise.connect(nf);nf.connect(ng);ng.connect(master);noise.start();audioState.noiseGain=ng;audioState.rivals=[];for(let i=0;i<3;i++){const osc=ctx.createOscillator(),gain=ctx.createGain(),pan=ctx.createStereoPanner();osc.type='triangle';osc.frequency.value=170;gain.gain.value=0;osc.connect(gain);gain.connect(pan);pan.connect(master);osc.start();audioState.rivals.push({osc,gain,pan});}}catch{toast('Áudio não disponível neste navegador.');}}
function audioTick(){if(!audioState.ctx)return;const ctx=audioState.ctx,active=race&&!paused&&!race.finish&&soundEnabled;audioState.gain.gain.setTargetAtTime(active?settings.volume/100*.45:0,ctx.currentTime,.08);if(!active)return;const rpm=race.rpm||4000;audioState.voices.forEach((v,i)=>v.frequency.setTargetAtTime(rpm/60*(i===1?2:1),ctx.currentTime,.05));audioState.filter.frequency.setTargetAtTime(600+race.player.speed*24,ctx.currentTime,.1);audioState.noiseGain.gain.setTargetAtTime(race.player.speed/450+race.rain*.15+(Math.abs(race.player.lane)>7?.1:0),ctx.currentTime,.15);const rivals=race.cars.filter(a=>a!==race.player).sort((a,b)=>Math.abs(a.d-race.player.d)-Math.abs(b.d-race.player.d));audioState.rivals?.forEach((v,i)=>{const car=rivals[i],gap=car?Math.abs(car.d-race.player.d):1000;v.gain.gain.setTargetAtTime(gap<75?.15*(1-gap/75):0,ctx.currentTime,.1);if(car){v.pan.pan.setTargetAtTime(clamp((car.lane-race.player.lane)/5,-1,1),ctx.currentTime,.1);v.osc.frequency.setTargetAtTime(100+car.speed*4,ctx.currentTime,.1);}});}
