let qualifiedGrid=9,qualifyingTrack=-1;
function startRace(session='race'){
 closeModal();initAudio();soundEnabled=true;audioState.ctx?.resume();resultShown=false;paused=false;cameraMode=0;keysClear();hiddenHud=false;document.querySelectorAll('.classification,.lap-panel,.telemetry,.map-wrap,#dashMirror,.race-hints').forEach(e=>e.style.visibility='visible');
 const config={...settings,...strategy,laps:session==='practice'?2:session==='qualify'?1:mode==='time'?5:+$('laps').value,weather:$('weather').value,mode,session};
 if(config.fuel<track.length*config.laps*.00045+1&&session==='race')toast('Atenção: combustível insuficiente para toda a distância.');
 race=new S.Race(track,config);if(mode==='career'){const u=profile.upgrades;race.config.aero=clamp(strategy.aero+(u.aero||0)*.3,1,10);race.config.powerBoost=1+(u.engine||0)*.025;race.config.brakeBoost=1+(u.brakes||0)*.025;race.config.gripBoost=1+(u.suspension||0)*.02;race.config.reliability=1-(u.reliability||0)*.12;race.player.damage=0;race.player.name=profile.name.toUpperCase().slice(0,16);race.player.battery=100;playerMesh.userData.helmet.material.color.set(profile.helmet);}
 if(qualifyingTrack===trackIndex&&session==='race'&&mode!=='time'){const grid=qualifiedGrid;race.cars.forEach((a,i)=>{if(i===9)return;let slot=i>9?i-1:i;if(slot>=grid)slot++;a.d=-slot*9;a.lane=slot%2?-2.4:2.4;});race.player.d=-grid*9;race.player.lane=grid%2?-2.4:2.4;race.position=grid+1;}
 $('menu').classList.add('hidden');$('hud').classList.remove('hidden');$('startLights').classList.remove('hidden');$('race').blur();document.activeElement?.blur();radioTimer=0;$('radio').style.opacity=0;meshes.forEach((m,i)=>m.visible=race.cars.some(a=>a.id===i));applyWeather(config.weather,race.wetness);updateHUD();
}
function pause(){if(!race||race.finish||paused)return;paused=true;keysClear();audioTick();window.speechSynthesis?.cancel();showModal('pause',`<div class="modal-eyebrow">${track.name.toUpperCase()} / VOLTA ${race.lap()}</div><h2>Respire. A pista espera.</h2><p>Posição P${race.position} · ${Math.round(race.player.speed*3.6)} km/h · ${race.player.fuel.toFixed(1)} kg de combustível</p><div class="modal-actions"><button class="primary" id="resume">VOLTAR À CORRIDA <span>↗</span></button><button class="secondary" id="pitStrategy">ESTRATÉGIA DE BOXES</button><button class="secondary" id="pauseSettings">CONFIGURAÇÕES</button><button class="secondary" id="restart">REINICIAR SESSÃO</button><button class="secondary" id="leave">VOLTAR AO MENU</button></div>`);$('resume').onclick=resume;$('pitStrategy').onclick=()=>strategyModal(true);$('pauseSettings').onclick=settingsModal;$('restart').onclick=()=>startRace(race.config.session);$('leave').onclick=returnMenu;}
function resume(){paused=false;keysClear();$('modalBackdrop').classList.add('hidden');activeModal='';audioState.ctx?.resume();}
function returnMenu(){race=null;paused=false;resultShown=false;keysClear();$('hud').classList.add('hidden');$('menu').classList.remove('hidden');$('modalBackdrop').classList.add('hidden');activeModal='';$('weatherFX').getContext('2d').clearRect(0,0,innerWidth,innerHeight);$('speedFX').style.opacity=0;meshes.forEach(m=>m.visible=true);meshes.forEach((m,i)=>place(m,-i*9,i%2?-2.4:2.4));scMesh.visible=false;applyWeather($('weather').value);audioTick();window.speechSynthesis?.cancel();}
function finishRace(){if(resultShown)return;resultShown=true;const p=race.player,session=race.config.session;window.speechSynthesis?.cancel();if(session==='qualify'){const ref=track.length/56,lap=race.best||race.time;qualifiedGrid=clamp(Math.round((lap/ref-1)*50)+6,0,19);qualifyingTrack=trackIndex;showModal('result',`<div class="modal-eyebrow">CLASSIFICAÇÃO ENCERRADA</div><h2>P${qualifiedGrid+1} no grid.</h2><p>Sua volta: ${timeFormat(lap)}. O tempo foi comparado ao ritmo de referência do pelotão.</p><button class="primary" id="resultContinue">IR PARA A CORRIDA <span>↗</span></button>`);$('resultContinue').onclick=()=>startRace('race');return;}
 if(session==='practice'){showModal('result',`<div class="modal-eyebrow">TREINO LIVRE ENCERRADO</div><h2>Pista reconhecida.</h2><p>Melhor volta: ${timeFormat(race.best)}.</p><div class="modal-actions"><button class="primary" id="resultContinue">CLASSIFICAÇÃO <span>↗</span></button><button class="secondary" id="practiceMenu">MENU</button></div>`);$('resultContinue').onclick=()=>startRace('qualify');$('practiceMenu').onclick=returnMenu;return;}
 const points=[25,18,15,12,10,8,6,4,2,1][race.position-1]||0;let extra='';
 if((mode==='career'||mode==='championship')&&!race.dnf){profile.points+=points;profile.round++;if(mode==='career'){profile.credits+=40+points*4;profile.reputation=clamp(profile.reputation+Math.max(2,22-race.position)-race.collisions*3,0,100);}if(profile.round>=6){extra=`Temporada concluída: ${profile.points} pontos. Uma nova temporada está disponível.`;profile.round=0;profile.season++;profile.lastSeasonPoints=profile.points;profile.points=0;}save();}
 if(mode==='time'&&race.best){const k='apex-best-'+trackIndex,previous=+(localStorage.getItem(k)||Infinity);if(race.best<previous){try{localStorage.setItem(k,String(race.best));}catch{}extra='Novo recorde pessoal neste circuito!';}}
 showModal('result',`<div class="modal-eyebrow">${race.dnf?'FIM DA SESSÃO':'BANDEIRA QUADRICULADA'}</div><h2>${race.dnf?'Sem combustível.':mode==='time'?'Cada milésimo conta.':`P${race.position}. Até a próxima curva.`}</h2><div class="split-stat"><div><b>${timeFormat(race.best)}</b><span>MELHOR VOLTA</span></div><div><b>${race.pitCount}</b><span>PARADAS</span></div><div><b>${points}</b><span>PONTOS</span></div></div><p>Tempo total: ${timeFormat(race.time+race.penalty)}${race.penalty?' · Inclui '+race.penalty+' s de penalidades':''}. ${extra}</p><table class="result-table"><tbody>${race.rank().slice(0,10).map((a,i)=>`<tr class="${a===p?'you':''}"><td>${i+1}</td><td>${escapeHTML(a.name)}</td><td>${a===p?'VOCÊ':((p.d-a.d)/Math.max(30,a.speed)>0?'+':'')+((p.d-a.d)/Math.max(30,a.speed)).toFixed(1)+' s'}</td></tr>`).join('')}</tbody></table><div class="modal-actions"><button class="primary" id="resultContinue">${mode==='career'||mode==='championship'?'PRÓXIMA ETAPA':'CORRER NOVAMENTE'} <span>↗</span></button><button class="secondary" id="resultMenu">MENU PRINCIPAL</button></div>`);$('resultContinue').onclick=()=>{if(mode==='career'||mode==='championship'){setTrack(profile.round%6);qualifiedGrid=9;qualifyingTrack=-1;}startRace();};$('resultMenu').onclick=returnMenu;
}
function updateMode(){document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===mode);b.setAttribute('aria-selected',b.dataset.mode===mode);});$('modeDescription').textContent=({gp:'Corrida rápida · Largada em P10',career:`${profile.team} · Temporada ${profile.season}`,championship:`Temporada ${profile.season} · ${profile.points} pontos · Etapa ${profile.round+1}/6`,time:'Pista livre · Recordes salvos neste navegador'})[mode]+` · Câmbio ${settings.automatic?'automático':'manual'}`;}
function updateHUD(){if(!race)return;const p=race.player,rank=race.rank(),idx=rank.indexOf(p),first=clamp(idx-2,0,Math.max(0,rank.length-5));$('position').textContent=race.position;document.querySelector('.position>span').firstChild.textContent='/ '+race.cars.length;$('lap').innerHTML=race.lap()+` <small>/ ${race.config.laps}</small>`;$('lapTime').textContent=timeFormat(race.time-race.lapStart);$('lastLap').textContent=timeFormat(race.last);$('bestLap').textContent=timeFormat(race.best);$('speed').textContent=Math.round(p.speed*3.6);$('gear').textContent=p.speed>1?p.gear:'N';$('rpm').textContent=Math.round(race.rpm/100)*100+' RPM';$('leaderboard').innerHTML=rank.slice(first,first+5).map((a,i)=>`<div class="leader ${a===p?'you':''}"><span>${i+first+1}</span><b>${escapeHTML(a===p?'VOCÊ':a.name)}</b><em>${a===p?'INTERVALO':(a.d>p.d?'-':'+')+(Math.abs(a.d-p.d)/Math.max(30,a.speed)).toFixed(1)}</em></div>`).join('');$('batteryBar').style.width=p.battery+'%';$('batteryValue').textContent=Math.round(p.battery)+'%';$('fuelBar').style.width=p.fuel/race.config.fuel*100+'%';$('fuelValue').textContent=p.fuel.toFixed(1)+' kg';$('tyreCondition').textContent=Math.round(p.condition*100)+'%';$('tyreTemp').textContent=Math.round(p.temp)+'°C';$('tyreCode').textContent=S.TYRES[p.tyre].code;$('tyreCode').style.color=S.TYRES[p.tyre].color;$('tyreCode').style.borderColor=S.TYRES[p.tyre].color;$('damageValue').textContent='CARRO '+Math.round((1-p.damage)*100)+'%';$('ersMode').textContent=['ECONÔMICO','NORMAL','ATAQUE','ULTRAPASSAGEM'][race.ersMode];$('drs').className='drs'+(race.drs?' on':race.drsAvailable?' available':'');$('drs').textContent=race.drs?'DRS ATIVO':'DRS';const flagNames={green:'● BANDEIRA VERDE',yellow:'● BANDEIRA AMARELA',vsc:'◆ VIRTUAL SAFETY CAR',sc:'◆ SAFETY CAR',checkered:'▦ BANDEIRA QUADRICULADA',red:'● BANDEIRA VERMELHA',warning:'◩ ADVERTÊNCIA — LIMITES DE PISTA'};$('flag').textContent=race.blueFlag&&race.flag==='green'?'● BANDEIRA AZUL':flagNames[race.flag];$('flag').style.color=race.flag==='red'?'#ff5061':race.blueFlag&&race.flag==='green'?'#56b2ff':['yellow','vsc','sc','warning'].includes(race.flag)?'#ffcc58':'#d8ff3e';$('weatherLabel').textContent=(race.wetness>.65?'CHUVA INTENSA':race.wetness>.25?'PISTA MOLHADA':'PISTA SECA')+' · '+Math.round(32-race.wetness*12)+'°C';$('sessionLabel').textContent=({race:mode==='time'?'CONTRA O RELÓGIO':'GRAND PRIX',practice:'TREINO LIVRE',qualify:'CLASSIFICAÇÃO'})[race.config.session];document.querySelectorAll('#sectorBars i').forEach((el,i)=>el.classList.toggle('active',mod(p.d,track.length)/track.length>=i/3));document.querySelector('.map-wrap').style.display=settings.minimap?'':'none';drawMap($('minimap'),true);updateDash();
 if(race.pit){$('pitNotice').classList.remove('hidden');$('pitNotice').textContent=race.pitState==='service'?`TROCA DE PNEUS · ${Math.max(0,race.pitTimer).toFixed(1)} s`:'PIT LANE · LIMITE 80 KM/H'+(race.pitState==='entry'?' · PARE NA MARCA AMARELA':' · SAÍDA LIBERADA');}else if(race.pitRequested){$('pitNotice').classList.remove('hidden');$('pitNotice').textContent='BOX CONFIRMADO · ENTRE À DIREITA ANTES DA RETA PRINCIPAL';}else $('pitNotice').classList.add('hidden');
}
function keysClear(){for(const k of Object.keys(keys))delete keys[k];for(const k of Object.keys(touchKeys))delete touchKeys[k];}
function action(code){if(code==='Escape'){if(race&&!race.finish){paused?resume():pause();}else closeModal();return;}if(!race||paused||race.finish)return;switch(code){case 'KeyF':race.toggleDRS();break;case 'KeyB':race.requestPit();break;case 'KeyV':race.cycleERS();break;case 'KeyE':if(!settings.automatic)race.shift(1);break;case 'KeyQ':if(!settings.automatic)race.shift(-1);break;case 'KeyC':cameraMode=(cameraMode+1)%3;break;case 'KeyR':race.message(`P${race.position}. ${race.gap!==null?'Carro à frente a '+race.gap.toFixed(1)+' segundos. ':''}Pneus em ${Math.round(race.player.condition*100)}%. Combustível: ${race.player.fuel.toFixed(1)} quilos.`);break;case 'KeyH':hiddenHud=!hiddenHud;document.querySelectorAll('.classification,.lap-panel,.telemetry,.map-wrap,#dashMirror,.race-hints').forEach(e=>e.style.visibility=hiddenHud?'hidden':'visible');break;case 'KeyX':race.player.lane=0;race.player.yaw=0;race.player.speed=Math.min(10,race.player.speed);race.penalty+=5;race.message('Carro reposicionado. Cinco segundos adicionados ao tempo final.');break;}}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Escape'].includes(e.code))e.preventDefault();if(!keys[e.code])action(e.code);keys[e.code]=true;});window.addEventListener('keyup',e=>delete keys[e.code]);window.addEventListener('blur',()=>{keysClear();if(race&&!paused&&!race.finish)pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&race&&!paused&&!race.finish)pause();});window.addEventListener('contextmenu',e=>{if(race)e.preventDefault();});window.addEventListener('pointermove',e=>{if(race&&e.buttons===2)lookTarget=clamp((e.clientX/innerWidth-.5)*2,-1,1);});window.addEventListener('pointerup',()=>lookTarget=0);
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();touchKeys[b.dataset.key]=true;b.setPointerCapture(e.pointerId);};b.onpointerup=b.onpointercancel=()=>delete touchKeys[b.dataset.key];});
function readInput(){const held=k=>keys[k]||touchKeys[k];let input={throttle:held('KeyW')||held('ArrowUp')?1:0,brake:held('KeyS')||held('ArrowDown')?1:0,steer:(held('KeyD')||held('ArrowRight')?1:0)-(held('KeyA')||held('ArrowLeft')?1:0),boost:!!held('Space')};const pad=navigator.getGamepads?.()?.find(g=>g);if(pad){const val=i=>pad.buttons[i]?.value||0;input.throttle=Math.max(input.throttle,val(7));input.brake=Math.max(input.brake,val(6));if(Math.abs(pad.axes[0]||0)>.12)input.steer=pad.axes[0];if(Math.abs(pad.axes[2]||0)>.12)lookTarget=pad.axes[2];input.boost||=val(0)>.5;for(const [i,code]of [[4,'KeyQ'],[5,'KeyE'],[2,'KeyF'],[3,'KeyR'],[9,'Escape'],[1,'KeyB']]){if(val(i)>.5&&!pressedPad[i])action(code);pressedPad[i]=val(i)>.5;}}return input;}
function weatherFX(dt){const c=$('weatherFX'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);if(!race||race.rain<.1)return;rainClock+=dt;const n=Math.floor(race.rain*105);ctx.strokeStyle='#c5e3ef55';ctx.lineWidth=1;for(let i=0;i<n;i++){const x=mod(i*137.13+rainClock*60,c.width),y=mod(i*83.3+rainClock*(750+i%10*30),c.height);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-9,y+25);ctx.stroke();}for(let i=0;i<n/4;i++){const x=mod(i*227.7,c.width),y=mod(i*123.7+rainClock*(9+i%6),c.height);const g=ctx.createRadialGradient(x,y,1,x,y,5+i%4);g.addColorStop(0,'#8ba6b518');g.addColorStop(.8,'#cbe3ee30');g.addColorStop(1,'#edffff08');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(x,y,5+i%4,7+i%5,.3,0,Math.PI*2);ctx.fill();}if(race.gap!==null&&race.gap<1&&race.player.speed>25){const grd=ctx.createRadialGradient(c.width/2,c.height*.5,0,c.width/2,c.height*.5,c.width*.4);grd.addColorStop(0,`rgba(191,207,212,${race.rain*.23})`);grd.addColorStop(1,'transparent');ctx.fillStyle=grd;ctx.fillRect(0,0,c.width,c.height);}}
function updateCamera(dt){let target=new T.Vector3(),pos=new T.Vector3();if(!race){menuTime+=dt;const m=playerMesh;m.userData.helmet.visible=true;place(m,-90,-2.4);const a=.12*Math.sin(menuTime*.12);m.updateMatrixWorld();pos.set(6.6+Math.sin(a)*4,2.5,-8.5).applyMatrix4(m.matrixWorld);target.set(-1.3,.72,-.2).applyMatrix4(m.matrixWorld);camera.position.copy(pos);camera.lookAt(target);camera.fov=48;camera.updateProjectionMatrix();return;}
 const p=race.player;playerMesh.userData.helmet.visible=cameraMode!==0;playerMesh.updateMatrixWorld();look=lerp(look,lookTarget,Math.min(1,dt*6));const vibration=settings.motion?(Math.sin(race.time*74)*.0025+Math.sin(race.time*43)*.002)*p.speed/70:0;const curb=Math.abs(p.lane)>7&&Math.abs(p.lane)<8.2?Math.sin(race.time*57)*.018:0;
 if(cameraMode===0){pos.set(0,1.43+vibration+curb,.39);target.set(Math.sin(look*1.3)*7,1.18,-Math.cos(look*1.3)*9);playerMesh.userData.steering.visible=true;}else if(cameraMode===1){pos.set(0,3.6,7.2);target.set(0,.75,-12);}else{pos.set(0,1.04,-2.2);target.set(0,.95,-14);}
 pos.applyMatrix4(playerMesh.matrixWorld);target.applyMatrix4(playerMesh.matrixWorld);camera.position.copy(pos);camera.lookAt(target);if(settings.motion&&cameraMode===0)camera.rotateZ(-p.steer*.012);camera.fov=lerp(camera.fov,settings.fov+(settings.motion?clamp((p.speed-50)*.16,0,8):0),Math.min(1,dt*3));camera.updateProjectionMatrix();$('speedFX').style.opacity=settings.motion?clamp((p.speed*3.6-245)/150,0,.45):0;
}
let fpsFrames=0,fpsTime=0,currentFPS=0;
function frame(ms){requestAnimationFrame(frame);const dt=Math.min((ms-lastFrame)/1000||.016,.1);lastFrame=ms;fpsFrames++;fpsTime+=dt;if(fpsTime>=1){currentFPS=Math.round(fpsFrames/fpsTime);fpsFrames=0;fpsTime=0;}
 if(race&&!paused&&!race.finish){const input=readInput();accumulator+=dt;while(accumulator>=1/120){race.step(1/120,input);accumulator-=1/120;}if(mode==='career'){const u=profile.upgrades;race.player.battery=clamp(race.player.battery+(u.energy||0)*dt*.08,0,100);race.player.temp-=Math.max(0,race.player.temp-95)*(u.suspension||0)*dt*.002;}
  if(race.phase==='start'){const count=clamp(Math.floor((6.4-race.countdown)/.85),0,5);document.querySelectorAll('#startLights i').forEach((e,i)=>e.classList.toggle('lit',i<count));document.querySelector('#startLights span').textContent=count<5?'PREPARE-SE':'AGUARDE AS LUZES';}else $('startLights').classList.add('hidden');
  for(const a of race.cars){const m=meshes[a.id];place(m,a.d,a.lane,a.yaw||0);m.userData.wheels.forEach((w,i)=>{if(i%2===0)w.rotation.y=-(a.steer||0)*.18;});m.userData.wing.rotation.x=a===race.player&&race.drs?-.5:0;}
  playerMesh.userData.steering.rotation.z=-race.player.steer*.47;playerMesh.userData.frontWing.scale.x=race.player.damage>.3?.68:1;playerMesh.userData.wheels.forEach(w=>w.visible=!(race.pitState==='service'&&race.pitTimer>1&&race.pitTimer<2.5));
  scMesh.visible=race.flag==='sc';if(scMesh.visible)place(scMesh,race.rank()[0].d+35,0);
  mechanics.forEach(({worker,x,z},i)=>{const active=race.pitState==='service';worker.position.x=active?Math.sign(x)*(1.4+Math.sin(race.time*8+i)*.08):x;worker.rotation.z=active?Math.sign(x)*-.2:0;worker.userData.spare.rotation.x=active?race.time*3:0;});
  if(race.messages.length&&radioTimer<=0){radio(race.messages.shift());}radioTimer-=dt;if(radioTimer<=0)$('radio').style.opacity=0;
  $('damageFlash').style.opacity=race.flash;hudClock+=dt;if(hudClock>.09){updateHUD();applyWeather(race.config.weather,race.wetness);hudClock=0;}weatherFX(dt);if(race.finish){updateHUD();setTimeout(finishRace,800);}
 }else if(!race){hudClock+=dt;if(hudClock>.3){updateDash();hudClock=0;}}
 if(!paused)updateCamera(dt);audioTick();const base=race?playerMesh.position:playerMesh.position;sun.position.set(base.x+90,base.y+125,base.z-100);sun.target.position.copy(base);sky.position.copy(camera.position);renderer.render(scene,camera);
}
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();$('weatherFX').width=innerWidth;$('weatherFX').height=innerHeight;}
window.addEventListener('resize',resize);$('race').onclick=()=>mode==='career'?careerModal():mode==='championship'?(setTrack(profile.round%6),weekendModal()):mode==='time'?startRace():weekendModal();$('settingsButton').onclick=settingsModal;$('strategyButton').onclick=()=>strategyModal();$('helpButton').onclick=helpModal;$('closeModal').onclick=closeModal;$('pauseButton').onclick=pause;$('nextTrack').onclick=()=>setTrack(trackIndex+1);$('prevTrack').onclick=()=>setTrack(trackIndex-1);$('weather').onchange=()=>applyWeather($('weather').value,$('weather').value==='storm'?.9:$('weather').value==='light'?.4:0);$('laps').onchange=()=>{strategy.fuel=Math.ceil(track.length*+$('laps').value*.00045+4);strategy.pitLap=Math.max(2,Math.round(+$('laps').value*.55));};$('sound').onclick=()=>{initAudio();soundEnabled=!soundEnabled;audioState.ctx?.resume();toast(soundEnabled?'Áudio ativado. O motor começa na pista.':'Áudio silenciado.');};$('onlineButton').onclick=()=>showModal('online','<div class="modal-eyebrow">EDIÇÃO LOCAL</div><h2>Multiplayer online.</h2><p>Esta versão funciona offline, com até 19 adversários de IA. Corridas online ainda não estão implementadas: exigem servidor de partidas e sincronização entre jogadores.</p><button class="primary" id="onlineClose">VOLTAR AO PADDOCK <span>↗</span></button>')||($('onlineClose').onclick=closeModal);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;updateMode();});
 // Read-only diagnostics support reproducible local verification.
 window.apex={get race(){return race;},get track(){return track;},get fps(){return currentFPS;},get rendererInfo(){return {calls:renderer.info.render.calls,triangles:renderer.info.render.triangles};}};
 buildWorld();resize();applyWeather($('weather').value);updateMode();updateDash();$('loading').classList.add('hidden');requestAnimationFrame(frame);
